import{_ as r,a0 as l,w as p,s,I as a,x as e,a1 as o,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"使用 GNOME 在 Fedora 中啓用分數縮放 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GNOME 在 Fedora 中啓用分數縮放 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GNOME 在 Fedora 中啓用分數縮放 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GNOME 在 Fedora 中啓用分數縮放 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230529.0 ⭐️⭐️ Enable Fractional Scaling in Fedora with GNOME","title":"使用 GNOME 在 Fedora 中啓用分數縮放","tag":"202306","desc":""},"relativePath":"202306/20230529.0 ⭐️⭐️ Enable Fractional Scaling in Fedora with GNOME.md","filePath":"[post].md"}'),u={name:"202306/20230529.0 ⭐️⭐️ Enable Fractional Scaling in Fedora with GNOME.md"};function g(m,t,f,b,w,F){const n=l("Link");return p(),s("div",null,[t[18]||(t[18]=a("h1",{id:"使用-gnome-在-fedora-中啓用分數縮放",tabindex:"-1"},[e("使用 GNOME 在 Fedora 中啓用分數縮放 "),a("a",{class:"header-anchor",href:"#使用-gnome-在-fedora-中啓用分數縮放","aria-label":"Permalink to “使用 GNOME 在 Fedora 中啓用分數縮放”"},"​")],-1)),t[19]||(t[19]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/27/155914j288s2lh4ovkx6jk.jpg",alt:""})],-1)),t[20]||(t[20]=a("blockquote",null,[a("p",null,"以下是在 GNOME 版本的 Fedora 工作站中啓用分數縮放的步驟。")],-1)),a("p",null,[a("ruby",null,[o(n,{href:"https://wiki.gnome.org/Initiatives/FracionalScaling"},{default:i(()=>[...t[0]||(t[0]=[e("分數縮放",-1)])]),_:1}),t[1]||(t[1]=a("rt",null,"Fractional Scaling",-1))]),t[2]||(t[2]=e(" 是一項方便的功能，可讓你最大程度地優化 HiDPI 顯示器和高分辨率筆記本電腦。通過微調縮放比例，你可以創建平衡良好、既不太大也不太小且美觀的桌面顯示。雖然通過分辨率設置也可以，但由於操作系統的限制，它們通常符合你的實際情況。",-1))]),t[21]||(t[21]=d('<p>此外，它還允許你增加顯示屏上文本和其他 UI 元素的大小，而不會使所有內容顯得模糊。如果你有高分辨率顯示器並希望使文本更易於閲讀，這將很有用。</p><p>Ubuntu 20.04 LTS 在 2020 年引入了 100%、125%、150%、175% 和 200% 的分數縮放。它可以在“<ruby>顯示<rt>Display</rt></ruby>”頁面下的“<ruby>設置<rt>Settings</rt></ruby>”中找到。</p><p>但在默認 GNOME 桌面的 Fedora 工作站中，只有 100% 和 200% 縮放可用。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Default-Scaling-in-GNOME-in-Fedora.jpg" alt="Fedora 中 GNOME 的默認縮放"></p><h3 id="如何使用-gnome-在-fedora-中啓用分數縮放" tabindex="-1">如何使用 GNOME 在 Fedora 中啓用分數縮放 <a class="header-anchor" href="#如何使用-gnome-在-fedora-中啓用分數縮放" aria-label="Permalink to “如何使用 GNOME 在 Fedora 中啓用分數縮放”">​</a></h3><p>打開終端窗口（<code>CTRL+ALT+T</code>）。</p><p>運行以下命令。此命令在帶有 GNOME 的 Fedora 中啓用 125%、150% 和 175% 縮放因子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.mutter experimental-features &quot;[&#39;scale-monitor-framebuffer&#39;]&quot;</span></span></code></pre></div><p>重啓 Fedora。</p><p>打開 “設置” 應用，你應該會看到新的縮放因子。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Fractional-Scaling-in-Fedora-with-GNOME.jpg" alt="在 GNOME Fedora 中進行分數縮放"></p><p>但是，重要的是要注意分數縮放並不總是完美的。某些應用程序可能無法正確縮放。例如，如果應用程序設計不當，非 GTK 應用可能看起來很模糊。</p><p>此外，請務必注意，由於 GPU 的渲染工作量更大，分數縮放可能會增加筆記本電腦的功耗。</p><h3 id="一些使用説明" tabindex="-1">一些使用説明 <a class="header-anchor" href="#一些使用説明" aria-label="Permalink to “一些使用説明”">​</a></h3><p>根據我的測試，上述命令在 Wayland 中應該是有效的。</p><p>如果你不想使用上述命令，但仍想獲得類似的體驗，那麼你可以按照以下步驟操作：</p><p>使用 <code>sudo dnf install gnome-tweaks</code> 安裝 GNOME “<ruby>調整<rt>Tweaks</rt></ruby>” 應用。</p><p>轉到 “<ruby>字體<rt>Fonts</rt></ruby>” 設置並更改比例因子。</p><p>示例：如果你想保持 100% 縮放比例但想要更大的字體，請嘗試縮放比例設為 1.1 或 1.2。根據你的需要進行調整。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Font-scaling.jpg" alt="字體縮放"></p><ul><li>125%：這是分數縮放的典型值。它將文本大小和 UI 元素增加 25% 而不會使所有內容顯得模糊。</li><li>150%：對於想要放大文本和其他 UI 元素但又不想增加顯示分辨率的人來説，這是一個很好的值。</li><li>175%：對於想要使文本和其他 UI 元素變得非常大的人來説，這是一個很好的值。</li></ul><p>嘗試不同的縮放因子對於找到最適合你的縮放因子至關重要。最佳縮放因子將取決於你的顯示器尺寸、視力和偏好。</p><p>我希望本指南有所幫助。</p><p><em>（題圖：MJ/4346b556-57ed-4c76-b2c9-e651e0d229f5）</em></p><hr>',25)),a("p",null,[t[4]||(t[4]=e("via: ",-1)),o(n,{href:"https://www.debugpoint.com/fractional-scaling-fedora/"},{default:i(()=>[...t[3]||(t[3]=[e("https://www.debugpoint.com/fractional-scaling-fedora/",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=e("作者：",-1)),o(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...t[5]||(t[5]=[e("Arindam",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),o(n,{href:"https://github.com/lkxed/"},{default:i(()=>[...t[6]||(t[6]=[e("lkxed",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const k=r(u,[["render",g]]);export{N as __pageData,k as default};
